// What rooka writes into a Strava activity's description: "Generated by rooka" only for a
// workout rooka planned; an unplanned one is "Scored with rooka" (or gets no credit when its
// score isn't shared). Uses a throwaway database.
const path = require("path");
const os = require("os");
process.env.DB_PATH = path.join(os.tmpdir(), `rooka_strava_desc_test_${process.pid}.db`);

const assert = require("assert");
const { buildStravaUpdatePayload } = require("./services/utils");

const ALL_ON = { shareName: true, shareScore: true, shareStructure: true, shareLink: true };
const plan = { description: "Easy run", target_rooka: 40, steps_json: "[]" };

let p = buildStravaUpdatePayload("", plan, 42, ALL_ON);
assert.match(p.description, /Generated by rooka:\nrooka\.io/);
assert.strictEqual(p.name, "Easy run");

p = buildStravaUpdatePayload("", null, 42, ALL_ON);
assert.ok(!/Generated by/i.test(p.description), "an unplanned activity isn't 'generated by rooka'");
assert.match(p.description, /Actual: 42 rooka\n\nScored with rooka:\nrooka\.io/);
assert.strictEqual(p.name, undefined, "the athlete's own title stays");

p = buildStravaUpdatePayload("", null, 42, { ...ALL_ON, shareScore: false, shareStructure: false });
assert.strictEqual(p, null, "no plan and no score: nothing to write");

p = buildStravaUpdatePayload("Morning loop with Sam", null, 42, ALL_ON);
assert.match(p.description, /^Morning loop with Sam\n\n---\nActual: 42 rooka/, "the athlete's text comes first");

assert.strictEqual(buildStravaUpdatePayload("Nice\n\n---\nActual: 42 rooka\n\nScored with rooka:\nrooka.io", null, 42, ALL_ON), null, "tagged once, not twice");

console.log("✅ Strava descriptions: 'Generated by rooka' only for planned workouts");
process.exit(0);
